options.styles:
*{box-sizing:border-box;}

.sech { height:100%; display:flex; align-items:center; justify-content:center;
         font-family:'Barlow Condensed','Arial Narrow',sans-serif; font-weight:700;
         letter-spacing:.16em; text-transform:uppercase; color:#e8efe9; font-size:30px;
         border-bottom:2px solid rgba(70,160,110,0.28); background:rgba(34,199,106,0.04); }

*{box-sizing:border-box;}

.kwrap{
  width:100%;
  height:100%;
  display:grid;
  gap:6px;
  padding:0;
  grid-auto-rows:minmax(0,1fr);
  overflow:hidden;
  container-type:inline-size;
}
.cols-1{grid-template-columns:1fr;}
.cols-2{grid-template-columns:repeat(2,minmax(0,1fr));}
.cols-3{grid-template-columns:repeat(3,minmax(0,1fr));}
.cols-4{grid-template-columns:repeat(4,minmax(0,1fr));}

.kcard{
  display:flex;
  flex-direction:column;
  justify-content:center;
  min-width:0;
  min-height:0;
  overflow:hidden;
  padding:0 14px;
  border:1px solid rgba(70,160,110,0.18);
  border-left:4px solid #3cdcaa;
  border-radius:6px;
  background:#0b100c;
}
.kcard .lbl{
  font-size:30px;
  line-height:1.02;
  color:#9db3a4;
  letter-spacing:.02em;
  font-family:'Barlow Condensed','Arial Narrow',sans-serif;
  text-transform:uppercase;
  margin-bottom:3px;
  white-space:normal;
  overflow:hidden;
  display:-webkit-box;
  -webkit-line-clamp:2;
  -webkit-box-orient:vertical;
}
.kcard .val{
  font-family:'Barlow Condensed','Arial Narrow',sans-serif;
  font-weight:700;
  font-size:96px;
  line-height:.96;
  letter-spacing:.01em;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.kcard .pill{
  margin-top:3px;
  align-self:flex-start;
  font-size:38px;
  line-height:1.05;
  padding:1px 7px;
  border-radius:8px;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  max-width:100%;
}
.p-bad{background:rgba(255,59,48,0.22);color:#ff3b30;}
.p-good{background:rgba(34,199,106,0.16);color:#2fe98d;}
.p-flat{background:rgba(157,179,164,0.15);color:#9db3a4;}

/* Responsive safety fallbacks.
   At the 15840px-wide wall, Grafana grid panels stay on the 18/48 default.
   These only activate on much narrower windows/panels. */
@container (max-width:520px){
  .kcard .lbl{font-size:30px;}
  .kcard .val{font-size:96px;}
  .kcard .pill{font-size:38px;}
}
@container (max-width:360px){
  .kwrap{gap:6px;padding:0;}
  .kcard{padding:0 14px;}
  .kcard .lbl{font-size:30px;margin-bottom:2px;}
  .kcard .val{font-size:96px;}
  .kcard .pill{font-size:38px;}
}
@container (max-width:260px){
  .kcard .lbl{font-size:30px;}
  .kcard .val{font-size:96px;}
  .kcard .pill{font-size:38px;}
}

options.afterRender:
(function () {
  const root = context.element;
  const dt = root.querySelector('[data-hclk="date"]');
  const tm = root.querySelector('[data-hclk="time"]');
  function tick() {
    try {
      const n = new Date();
      const dmy = n.toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' }).toUpperCase();
      if (dt) dt.textContent = dmy + ' · LIVE';
      if (tm) tm.textContent = n.toLocaleTimeString('en-GB', { hour12: false }) + ' AST';
    } catch (e) { }
  }
  tick();
  if (window.__nocHdrClk) clearInterval(window.__nocHdrClk);
  window.__nocHdrClk = setInterval(tick, 1000);

  const aramcoImg = root.querySelector('img.aramco');
  if (aramcoImg && !root.querySelector('.aramco-wrap')) {
    const wrap = document.createElement('div');
    wrap.className = 'aramco-wrap';
    aramcoImg.parentNode.insertBefore(wrap, aramcoImg);
    const base = aramcoImg.cloneNode(true);
    base.className = 'hdr-logo aramco-base';
    aramcoImg.className = 'hdr-logo aramco-text-white';
    wrap.appendChild(base);
    wrap.appendChild(aramcoImg);
  }
})();

options.styles:
* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden !important;
}

.hdr {
  width: 100%;
  height: 100%;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 22px 0 28px;
  gap: 20px;

  background: transparent;
  color: #ffffff;

  overflow: hidden !important;
}

.hdr-left {
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;

  display: flex;
  align-items: center;
  justify-content: flex-start;

  overflow: hidden;
}

.hdr-title {
  font-family: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  font-weight: 800;

  font-size: clamp(18px, 2.2vw, 58px);
  letter-spacing: 0.08em;

  text-transform: uppercase;
  color: #ffffff;

  line-height: 1;
  white-space: nowrap;

  margin: 0;
  padding: 0;
}


/* RIGHT SIDE */

.hdr-right {
  flex: 0 0 auto;
  height: 100%;

  display: flex;
  align-items: center;
  justify-content: flex-end;

  gap: 18px;

  overflow: hidden;
  white-space: nowrap;
}


/* COMMON IMAGE RESET */

.hdr-logo {
  display: block;
  width: auto;

  object-fit: contain;

  margin: 0;
  padding: 0;

  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}


/* =========================================
   iCONNA — ENTIRE LOGO WHITE
   ========================================= */

.hdr-logo.iconna {
  height: 58%;
  max-height: 70%;
  max-width: 240px;

  filter: brightness(0) invert(1) !important;
}


/* =========================================
   ARAMCO DIGITAL
   WHITE TEXT + ORIGINAL COLORED ICON
   ========================================= */

.aramco-wrap {
  position: relative;

  height: 56px;
  width: 167px;

  flex: 0 0 auto;

  overflow: hidden;
}


/* ORIGINAL LOGO UNDERNEATH */

.aramco-base {
  position: absolute;

  inset: 0;

  width: 100%;
  height: 100%;

  object-fit: contain;
  object-position: center;

  margin: 0;
  padding: 0;

  border: 0;
  box-shadow: none;

  background: transparent;
}


/* WHITE VERSION ABOVE */

.aramco-text-white {
  position: absolute;

  inset: 0;

  width: 100%;
  height: 100%;

  object-fit: contain;
  object-position: center;

  margin: 0;
  padding: 0;

  border: 0;
  box-shadow: none;

  background: transparent;

  filter: brightness(0) invert(1);

  /*
     Only show the white version over the text.
     Right side containing the colored Aramco icon
     remains visible from the original image underneath.
  */

  clip-path: inset(0 31% 0 0);
}


/* REMOVE SCROLLBARS */

::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

html,
body,
.hdr,
.hdr * {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}


/* RESPONSIVE */

@media (max-width: 900px) {

  .hdr {
    padding: 0 12px;
    gap: 10px;
  }

  .hdr-title {
    font-size: clamp(14px, 3.5vw, 30px);
  }

  .hdr-right {
    gap: 10px;
  }

  .hdr-logo.iconna {
    height: 52%;
    max-width: 170px;
  }

  .aramco-wrap {
    height: 44px;
    width: 131px;
  }
}

