options.getOption:
const f = context.panel.data.series[0];

const names = f.fields.map(x => x.name);
const vals = f.fields.map(x => x.values[0]);

return {
  backgroundColor: 'transparent',

  radar: {
    indicator: names.map(n => ({
      name: n,
      max: 100
    })),

    axisName: {
      color: '#c9cdc9',
      fontSize: 20,
      fontWeight: 600
    },

    splitLine: {
      lineStyle: {
        color: 'rgba(255,255,255,0.18)'
      }
    },

    splitArea: {
      show: false
    },

    axisLine: {
      lineStyle: {
        color: 'rgba(255,255,255,0.18)'
      }
    }
  },

  series: [
    {
      type: 'radar',

      lineStyle: {
        color: '#2fe98d',
        width: 2
      },

      itemStyle: {
        color: '#2fe98d'
      },

      areaStyle: {
        color: 'rgba(34,199,106,0.22)'
      },

      data: [
        {
          value: vals,
          name: 'RAN Status'
        }
      ]
    }
  ]
};

