*{
  box-sizing:border-box;
  margin:0;
  padding:0;
}


/* =========================================================
   ONE HORIZONTAL ROW — NO WRAP — NO SCROLL — NO PADDING
   ========================================================= */

.kwrap{
  width:100%;
  height:100%;

  display:flex;
  flex-direction:row;
  flex-wrap:nowrap;

  align-items:stretch;
  justify-content:stretch;

  gap:0;
  padding:0;
  margin:0;

  overflow:hidden;

  container-type:inline-size;
}


/* Keep existing cols classes */
.cols-1,
.cols-2,
.cols-3,
.cols-4{
  display:flex;
  gap:0;
  padding:0;
  margin:0;
}


/* =========================================================
   KPI CARD
   ========================================================= */

.kcard{
  flex:1 1 0;

  width:0;
  min-width:0;
  max-width:100%;

  height:100%;
  min-height:0;

  display:flex;
  flex-direction:column;
  justify-content:center;
  align-items:flex-start;

  padding:0;
  margin:0;

  overflow:hidden;

  border:1px solid rgba(70,160,110,0.18);
  border-left:4px solid #3cdcaa;

  border-radius:0;

  background:#0b100c;
}


/* =========================================================
   LABEL
   ========================================================= */

.kcard .lbl{
  width:100%;
  min-width:0;

  padding:0;
  margin:0 0 2px 0;

  font-family:'Barlow Condensed','Arial Narrow',sans-serif;
  font-weight:600;

  font-size:30px;
  line-height:1;

  color:#9db3a4;

  letter-spacing:.025em;
  text-transform:uppercase;

  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}


/* =========================================================
   MAIN KPI VALUE — ALWAYS 96PX
   ========================================================= */

.kcard .val{
  width:100%;
  min-width:0;
  max-width:100%;

  padding:0;
  margin:0;

  font-family:'Barlow Condensed','Arial Narrow',sans-serif;
  font-weight:700;

  font-size:96px !important;
  line-height:.88;

  letter-spacing:.005em;

  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}


/* =========================================================
   STATUS PILL
   ========================================================= */

.kcard .pill{
  flex:0 0 auto;

  margin:2px 0 0 0;
  padding:2px 6px;

  max-width:100%;

  font-family:'Barlow Condensed','Arial Narrow',sans-serif;
  font-weight:600;

  font-size:24px;
  line-height:1;

  border-radius:6px;

  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}


/* =========================================================
   STATUS COLORS
   ========================================================= */

.p-bad{
  background:rgba(255,59,48,0.22);
  color:#ff3b30;
}

.p-good{
  background:rgba(34,199,106,0.16);
  color:#2fe98d;
}

.p-flat{
  background:rgba(157,179,164,0.15);
  color:#9db3a4;
}


/* =========================================================
   RESPONSIVE — STILL NO PADDING / NO GAP / NO SCROLL
   KPI VALUE REMAINS 96PX
   ========================================================= */

@container (max-width:900px){

  .kwrap{
    gap:0;
    padding:0;
    margin:0;
  }

  .kcard{
    padding:0;
    margin:0;
  }

  .kcard .lbl{
    font-size:22px;
    margin:0 0 2px 0;
  }

  .kcard .val{
    font-size:96px !important;
  }

  .kcard .pill{
    font-size:20px;
    padding:2px 5px;
    margin-top:2px;
  }
}


@container (max-width:500px){

  .kwrap{
    gap:0;
    padding:0;
    margin:0;
  }

  .kcard{
    padding:0;
    margin:0;
    border-left-width:3px;
  }

  .kcard .lbl{
    font-size:14px;
    margin:0;
  }

  .kcard .val{
    font-size:96px !important;
  }

  .kcard .pill{
    font-size:14px;
    padding:1px 4px;
    margin-top:1px;
  }
}


/* =========================================================
   EXTRA SAFETY — PREVENT GRAFANA/DYNAMIC TEXT SCROLL
   ========================================================= */

html,
body{
  margin:0;
  padding:0;
  overflow:hidden;
}

.kwrap,
.kcard,
.kcard *{
  scrollbar-width:none;
}

.kwrap::-webkit-scrollbar,
.kcard::-webkit-scrollbar{
  display:none;
}

